  check(pages.length === 2 && pages.every((page): boolean => page.state === "pending" && page.result === null), "페이지가 분리되지 않았어요."); checks.push("selected-pages-created-independently");
  const proof = await requireExtractionPage(DB, BUCKET, owner, transfer.materialId, 1, 1);
  const result: PageResult = { filePage: 1, method: "text-layer", status: "complete", width: 612, height: 792, rotation: 0, segments: [{ id: "s0", kind: "formula", text: "x² + y²", bounds: { x: 0.1, y: 0.1, width: 0.4, height: 0.1 }, transform: null, uncertain: true, reason: "수식 대조 필요" }, { id: "s1", kind: "table", text: "| A | B |\n| 1 | 2 |", bounds: { x: 0.1, y: 0.3, width: 0.5, height: 0.2 }, transform: null, uncertain: true, reason: "열 대조 필요" }], error: null, requiresConfirmation: true };
  const command = { owner, expectedVersion: 1, requestKey: crypto.randomUUID() };
  const receipt = await saveTextExtraction(DB, command, proof, pages[0], result);
  const replay = await saveTextExtraction(DB, command, proof, pages[0], result);
  check(JSON.stringify(receipt) === JSON.stringify(replay), "중복 저장 결과가 달라요.");
  const first = await getExtractionPage(DB, owner, pages[0].id);
  check(first.resultVersion === 1 && JSON.stringify(first.result) === JSON.stringify(result), "구조가 보존되지 않았어요."); checks.push("formula-table-uncertainty-and-idempotency");
  const proof2 = await requireExtractionPage(DB, BUCKET, owner, transfer.materialId, 1, 2);
  await saveTextExtraction(DB, { ...command, requestKey: crypto.randomUUID() }, proof2, pages[1], { ...result, filePage: 2, status: "failed", segments: [], error: "fixture-page-failure" });
  check((await getExtractionPage(DB, owner, pages[0].id)).resultVersion === 1, "다른 페이지가 바뀌었어요."); checks.push("partial-failure-preserves-completed-page");
  await rejected(() => saveTextExtraction(DB, { ...command, requestKey: crypto.randomUUID() }, proof, first, result));
  const outcomes = await Promise.allSettled(["A", "B"].map((suffix) => saveTextExtraction(DB, { owner, expectedVersion: first.version, requestKey: crypto.randomUUID() }, proof, first, { ...result, segments: [{ ...result.segments[0], text: suffix }] })));
  check(outcomes.filter((outcome): boolean => outcome.status === "fulfilled").length === 1, "CAS가 동시 갱신을 막지 못했어요."); checks.push("stale-and-concurrent-cas-rollback");
  const before = await getExtractionPage(DB, owner, first.id);
  const countBefore: number | null = await DB.prepare("SELECT COUNT(*) AS n FROM atomic_requests WHERE owner_id=?").bind(owner.userId).first<number>("n");
  await DB.prepare("CREATE TRIGGER fixture_result_failure BEFORE INSERT ON extraction_results BEGIN SELECT RAISE(ABORT,'fixture_middle_sql_failure'); END").run();
  await rejected(() => saveTextExtraction(DB, { owner, expectedVersion: before.version, requestKey: crypto.randomUUID() }, proof, before, result));
  await DB.prepare("DROP TRIGGER fixture_result_failure").run();
  check(JSON.stringify(await getExtractionPage(DB, owner, first.id)) === JSON.stringify(before), "결과 INSERT 실패 후 페이지 상태가 부분 커밋됐어요.");
  check(await DB.prepare("SELECT COUNT(*) AS n FROM atomic_requests WHERE owner_id=?").bind(owner.userId).first<number>("n") === countBefore, "실패 요청 영수증이 남았어요."); checks.push("middle-sql-error-rolls-back-page-result-receipt");
