  await confirmExtractionSegments(DB, { owner, expectedVersion: before.version, requestKey: crypto.randomUUID() }, proof, before, confirmation);
  const confirmed = await getExtractionPage(DB, owner, before.id);
  check(confirmed.confirmedSegmentIds.includes("s0") && confirmed.printedPage === "iii", "확인과 인쇄 쪽수 저장 실패");
  await rejected(() => confirmExtractionSegments(DB, { owner, expectedVersion: before.version, requestKey: crypto.randomUUID() }, proof, before, confirmation));
  await createExtractionSource(DB, { owner, expectedVersion: confirmed.version, requestKey: crypto.randomUUID() }, proof, confirmed, "s0");
  const sourceId: string | null = await DB.prepare("SELECT source_id FROM extraction_sources WHERE owner_id=? AND result_id=?").bind(owner.userId, confirmed.resultId).first<string>("source_id");
  check(sourceId !== null && (await resolveExtractionSource(DB, BUCKET, owner, sourceId!)).valid, "확인 출처가 조회되지 않아요.");
  await createExtractionSource(DB, { owner, expectedVersion: confirmed.version, requestKey: crypto.randomUUID() }, proof, confirmed, "s0");
  check(await DB.prepare("SELECT COUNT(*) AS n FROM extraction_sources WHERE owner_id=?").bind(owner.userId).first<number>("n") === 1, "출처가 중복 생성됐어요.");
  check(await readExtractionSource(DB, { realm: "sites", userId: "other" }, sourceId!) === null, "다른 소유자 출처가 노출됐어요.");
  const correction = { selectionRevision: 1, filePage: 1, expectedVersion: confirmed.version, resultId: confirmed.resultId!, segments: [{ id: "s0", text: "수정된 수식" }] };
  await saveExtractionCorrection(DB, { owner, expectedVersion: confirmed.version, requestKey: crypto.randomUUID() }, proof, confirmed, correction);
  const corrected = await getExtractionPage(DB, owner, before.id);
  const staleSource = await resolveExtractionSource(DB, BUCKET, owner, sourceId!);
  check(!staleSource.valid && staleSource.reason === "stale-result", "수정 전 출처가 유효해요.");
  await rejected(() => createExtractionSource(DB, { owner, expectedVersion: corrected.version, requestKey: crypto.randomUUID() }, proof, corrected, "s0"));
  checks.push("confirmed-source-deduplicated-owner-scoped-and-invalidated-after-edit");
  check(corrected.confirmedSegmentIds.length === 0 && corrected.result?.method === "manual-correction", "수정본이 이전 확인을 승계했어요.");
  await setExtractionPrintedPage(DB, { owner, expectedVersion: corrected.version, requestKey: crypto.randomUUID() }, proof, corrected, "iv");
  const ready = await getExtractionPage(DB, owner, before.id);
  check(ready.filePage === 1 && ready.printedPage === "iv" && ready.resultVersion === corrected.resultVersion, "표시 쪽수 변경이 원본 위치를 바꿨어요."); checks.push("confirmation-stale-write-edit-invalidation-and-printed-label");
  const image: ImageMetadata = { mime: "image/png", bytes: 1, sha256: "b".repeat(64), width: 100, height: 100, sourceWidth: 100, sourceHeight: 100, rotation: 0, sourceToImage: [1, 0, 0, 1, 0, 0], coordinateSpace: "pdf-viewport" };
  await beginVisionExtraction(DB, { owner, expectedVersion: ready.version, requestKey: crypto.randomUUID() }, proof, ready, "fixture-unknown-generation", image);
  const running = await getExtractionPage(DB, owner, before.id);
  await recordVisionFailure(DB, { owner, expectedVersion: running.version, requestKey: crypto.randomUUID() }, proof, running, "unknown", "fixture-result-unknown");
  const unknown = await getExtractionPage(DB, owner, before.id);
  await rejected(() => saveTextExtraction(DB, { owner, expectedVersion: unknown.version, requestKey: crypto.randomUUID() }, proof, unknown, result));
  check((await getExtractionPage(DB, owner, before.id)).pendingAiKey === "fixture-unknown-generation", "응답 불명 의도가 사라졌어요."); checks.push("unknown-ai-intent-not-overwritten-by-text");
  await saveExtractionSelection(DB, { owner, expectedVersion: 1, requestKey: crypto.randomUUID() }, transfer, selection);
  const latest = await listExtractionPages(DB, owner, transfer.materialId, 2);
  check(latest.every((page): boolean => page.result === null), "새 선택이 이전 결과를 확정 승계했어요.");
  await rejected(() => saveTextExtraction(DB, { owner, expectedVersion: unknown.version, requestKey: crypto.randomUUID() }, proof, unknown, result)); checks.push("old-selection-cannot-write-or-inherit-results");
  await rejected(() => getExtractionPage(DB, { realm: "sites", userId: "other" }, first.id)); checks.push("other-owner-page-read-denied");
  checks.push(...await checkTranscriptionState(DB, await requireExtractionPage(DB, BUCKET, owner, transfer.materialId, 2, 1), latest[0]));
